tool_input.command:
sed -i 's/for &c1 in &\[1e-6, 1e6\]/for \&c1 in \&[3e-6, 1e6]/' tests/audit_reference_oracle.rs && cat > tests/audit_zz_probe.rs <<'EOF'
use kalman_filters::linear::LinearKalmanFilter;
#[test]
fn probe() {
    for hb in [1.0/3.0, 0.1, 0.7, 1.0/7.0, 0.123456789, 2.0f64.sqrt()] {
    for &scale in &[1.0f64, 1e4, 1e6, 1e8, 1e12] {
        let h = [1.0, hb];
        let r = [h[0]*h[0]*scale, h[0]*h[1]*scale, h[1]*h[0]*scale, h[1]*h[1]*scale];
        let mut kf = LinearKalmanFilter::<f64>::new(1, 2, &[0.0], &[scale], &[1.0], &[0.0], &h, &r).unwrap();
        let res = kf.update(&[0.0, 1.0]);
        eprintln!("hb={hb} scale={scale:e} res={res:?} x={:?} p={:?}", kf.state(), kf.covariance());
    }}
}
EOF
cargo test --quiet --test audit_zz_probe -- --nocapture 2>&1 | grep "hb="

python3 - <<'EOF'
import re
p='tests/audit_reference_oracle.rs'
s=open(p).read()
old_start=s.index('#[test]\nfn audit_large_scale_singular_innovation_is_detected')
old_end=s.index('// ---------------------------------------------------------------------------\n// AUD-4')
new='''#[test]
fn audit_large_scale_singular_innovation_is_detected() {
    let mut bad = Vec::new();
    for &hb in &[1.0 / 3.0, 0.1, 0.7, 1.0 / 7.0, 0.123456789, std::f64::consts::SQRT_2] {
        for &scale in &[1.0f64, 1e4, 1e6, 1e8, 1e10, 1e12] {
            let h = [1.0, hb];
            let r = [h[0] * h[0] * scale, h[0] * h[1] * scale, h[1] * h[0] * scale, h[1] * h[1] * scale];
            let mut kf = LinearKalmanFilter::<f64>::new(1, 2, &[0.0], &[scale], &[1.0], &[0.0], &h, &r).unwrap();
            // z has a component orthogonal to range(S) = span(h).
            let res = kf.update(&[0.0, 1.0]);
            let x = st64(kf.state())[0];
            let p = st64(kf.covariance())[0];
            match res {
                Err(KalmanError::SingularMatrix) if (x, p) == (0.0, scale) => {}
                Ok(()) if x.is_finite() && x.abs() < 10.0 && p >= -1e-9 * scale && p <= scale => {}
                other => bad.push(format!("h=[1,{hb}] scale={scale:e}: {other:?}, x={x:e}, P={p:e}")),
            }
        }
    }
    assert!(bad.is_empty(), "singular S mishandled:\\n{}", bad.join("\\n"));
}

'''
s=s[:old_start]+new+s[old_end:]
open(p,'w').write(s)
EOF
